Mkt3L10n.socialAppDashboard = {
  Social_Dashboard: "à_Painel social_海",
  Date_of_Activity: "à_Data da atividade_海",
  Last_Updated: "à_Última atualização_海",
  Social_Funnel: "à_Canal social_海",
  Audience: "à_Público <span style='font-weight:normal'>(total de perfis: {0})</span>_海",
  Share_Metrics: "à_Métricas de compartilhamento_海",
  Share_Rate_percentage: "à_<div style=\"font-weight: bold\">Taxa de compartilhamentos:</div><p>A porcentagem de visitas que geram um compartilhamento.</p><br/><div style=\"font-weight: bold\">Taxa de retorno de cliques:</div> <p>O número de cliques resultantes por compartilhamento:</p><br/><div style=\"font-weight: bold\">Elevação social:</div><p>A proporção de visitais sociais (vindas de uma URL compartilhada) em relação ao número de visitas não sociais (vindas de outras origens), expressa em porcentagem.</p><br/>_海",
  Total_Profiles_number_users_who_signed_social_network: "à_<div style=\"font-weight: bold\">Total de perfis:</div><p>O número de usuários que entraram em uma rede social (ou interagiram) com um aplicativo social.</p><br/> <div style=\"font-weight: bold\">Influenciadores:</div><p>O número de usuários que geraram pelo menos uma visita indicada a partir de um link compartilhado.</p><br/><div style=\"font-weight: bold\">Alcance social:</div><p>O total de todas as conexões de usuários em uma campanha. Para usuários de redes sociais, contamos o número de amigos no momento do compartilhamento; para usuários de e-mail, contamos o número de destinatário do e-mail enviado.</p><br/><div style=\"font-weight: bold\">Impressões sociais:</div><p>O número de vezes que as mensagens compartilhadas de uma campanha podem ter sido vistas. Isso é calculado multiplicando-se o alcance social de cada compartilhador pelo número de compartilhamentos e somando esses valores para todos os compartilhadores.</p><br/>_海",
  Visits_number_sessions_Campaign: "à_<div style=\"font-weight: bold\">Visitas:</div><p>O número de vezes que os usuários estiveram em seu site (sessões únicas iniciadas pelos visitantes) durante um período específico. Os usuários que saem e retornam em 30 minutos serão contados como parte da sessão original. As interrupções nas atividades maiores do que 30 minutos ou um fechamento e reinicialização do navegador resultarão em uma nova sessão ou visita.</p><br/><div style=\"font-weight: bold\">Visitas a campanhas:</div><p>O número de visitas a todas as campanhas em seu site. As visitas a uma página com vários posicionamentos da mesma campanha contam como uma visita à campanha. As visitas a várias páginas posicionamentos da mesma campanha também contam como uma visita à campanha.</p><br/><div style=\"font-weight: bold\">Interações:</div><p>O número de vezes que os usuários concluíram uma ação social, como votar, classificar, compartilhar, postar um comentário, inscrever-se em uma oferta, compartilhar um vídeo e assim por diante. </p><br/><div style=\"font-weight: bold\">Compartilhamentos:</div><p>O número de vezes que os usuários compartilharam uma mensagem em uma rede social.</p><br/><div style=\"font-weight: bold\">Cliques resultantes:</div><p>O número de exibições de páginas geradas pelos links compartilhados de uma campanha.</p><br/><div style=\"font-weight: bold\">Conversões:</div><p>O número de vezes que os usuários concluíram uma ação específica (por exemplo, comprar um produto), conforme definido por um script de conversão implementado em seu site. \"Registros\" (ou usuários iniciantes que interagem como resultado de acessar um link compartilhado para seu site) é o evento de conversão padrão quando não há scripts de conversão implantados.</p><br/>_海",
  Data_will_be_updated_within_24_hours: "à_Os dados serão atualizados em 24 horas_海"
};

